1	// Package parser implements an AST parser for mini FreeLang
2	package parser
3	
4	import (
5		"fmt"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8		"github.com/user/freelang-evolving-compiler/internal/lexer"
9	)
10	
11	type Parser struct {
12		l         *lexer.Lexer
13		curToken  ast.Token
14		peekToken ast.Token
15	}
16	
17	// New creates a new parser for the input string
18	func New(input string) *Parser {
19		l := lexer.New(input)
20		p := &Parser{l: l}
21		p.nextToken()
22		p.nextToken()
23		return p
24	}
25	
26	func (p *Parser) nextToken() {
27		p.curToken = p.peekToken
28		p.peekToken = p.l.NextToken()
29	}
30	
31	// ParseProgram parses a complete program
32	func (p *Parser) ParseProgram() (*ast.Node, error) {
33		prog := &ast.Node{
34			Kind:     ast.NodeProgram,
35			Children: []*ast.Node{},
36		}
37	
38		for p.curToken.Type != ast.TokenEOF {
39			stmt, err := p.parseStatement()
40			if err != nil {
41				return nil, err
42			}
43			if stmt != nil {
44				prog.Children = append(prog.Children, stmt)
45			}
46			p.skipSemicolons()
47		}
48	
49		return prog, nil
50	}
51	
52	func (p *Parser) parseStatement() (*ast.Node, error) {
53		switch p.curToken.Type {
54		case ast.TokenLet:
55			return p.parseLetDecl()
56		case ast.TokenFn:
57			return p.parseFnDecl()
58		case ast.TokenIf:
59			return p.parseIfStmt()
60		case ast.TokenFor:
61			return p.parseForStmt()
62		case ast.TokenReturn:
63			return p.parseReturnStmt()
64		case ast.TokenStruct:
65			return p.parseStructDecl()
66		case ast.TokenLBrace:
67			return p.parseBlockStmt()
68		case ast.TokenSemicolon:
69			p.nextToken()
70			return nil, nil
71		default:
72			// Try to parse as expression statement
73			expr, err := p.parseExpression(0)
74			if err != nil {
75				return nil, err
76			}
77			return expr, nil
78		}
79	}
80	
81	func (p *Parser) parseLetDecl() (*ast.Node, error) {
82		letNode := &ast.Node{
83			Kind: ast.NodeLetDecl,
84			Line: p.curToken.Line,
85			Col:  p.curToken.Col,
86		}
87	
88		p.nextToken() // consume 'let'
89	
90		if p.curToken.Type != ast.TokenIdent {
91			return nil, fmt.Errorf("expected identifier after 'let'")
92		}
93	
94		nameNode := &ast.Node{
95			Kind:  ast.NodeIdent,
96			Value: p.curToken.Value,
97			Line:  p.curToken.Line,
98			Col:   p.curToken.Col,
99		}
100		letNode.Children = append(letNode.Children, nameNode)
101	
102		p.nextToken() // consume identifier
103	
104		if p.curToken.Type != ast.TokenAssign {
105			return nil, fmt.Errorf("expected '=' after identifier")
106		}
107	
108		p.nextToken() // consume '='
109	
110		expr, err := p.parseExpression(0)
111		if err != nil {
112			return nil, err
113		}
114		letNode.Children = append(letNode.Children, expr)
115	
116		return letNode, nil
117	}
118	
119	func (p *Parser) parseFnDecl() (*ast.Node, error) {
120		fnNode := &ast.Node{
121			Kind: ast.NodeFnDecl,
122			Line: p.curToken.Line,
123			Col:  p.curToken.Col,
124		}
125	
126		p.nextToken() // consume 'fn'
127	
128		if p.curToken.Type != ast.TokenIdent {
129			return nil, fmt.Errorf("expected function name")
130		}
131	
132		fnNode.Value = p.curToken.Value
133		p.nextToken()
134	
135		if p.curToken.Type != ast.TokenLParen {
136			return nil, fmt.Errorf("expected '(' after function name")
137		}
138	
139		p.nextToken()
140	
141		// Parse parameters (simplified: just identifiers)
142		for p.curToken.Type != ast.TokenRParen {
143			if p.curToken.Type != ast.TokenIdent {
144				return nil, fmt.Errorf("expected parameter name")
145			}
146			param := &ast.Node{
147				Kind:  ast.NodeIdent,
148				Value: p.curToken.Value,
149			}
150			fnNode.Children = append(fnNode.Children, param)
151			p.nextToken()
152	
153			if p.curToken.Type == ast.TokenColon {
154				p.nextToken()
155				if p.curToken.Type == ast.TokenIdent {
156					p.nextToken() // skip type for now
157				}
158			}
159	
160			if p.curToken.Type == ast.TokenComma {
161				p.nextToken()
162			}
163		}
164	
165		p.nextToken() // consume ')'
166	
167		if p.curToken.Type != ast.TokenLBrace {
168			return nil, fmt.Errorf("expected '{' for function body")
169		}
170	
171		body, err := p.parseBlockStmt()
172		if err != nil {
173			return nil, err
174		}
175		fnNode.Children = append(fnNode.Children, body)
176	
177		return fnNode, nil
178	}
179	
180	func (p *Parser) parseIfStmt() (*ast.Node, error) {
181		ifNode := &ast.Node{
182			Kind: ast.NodeIfStmt,
183			Line: p.curToken.Line,
184			Col:  p.curToken.Col,
185		}
186	
187		p.nextToken() // consume 'if'
188	
189		cond, err := p.parseExpression(0)
190		if err != nil {
191			return nil, err
192		}
193		ifNode.Children = append(ifNode.Children, cond)
194	
195		if p.curToken.Type != ast.TokenLBrace {
196			return nil, fmt.Errorf("expected '{' after if condition")
197		}
198	
199		body, err := p.parseBlockStmt()
200		if err != nil {
201			return nil, err
202		}
203		ifNode.Children = append(ifNode.Children, body)
204	
205		return ifNode, nil
206	}
207	
208	func (p *Parser) parseForStmt() (*ast.Node, error) {
209		forNode := &ast.Node{
210			Kind: ast.NodeForStmt,
211			Line: p.curToken.Line,
212			Col:  p.curToken.Col,
213		}
214	
215		p.nextToken() // consume 'for'
216	
217		if p.curToken.Type != ast.TokenIdent {
218			return nil, fmt.Errorf("expected iterator variable")
219		}
220	
221		iter := &ast.Node{
222			Kind:  ast.NodeIdent,
223			Value: p.curToken.Value,
224		}
225		forNode.Children = append(forNode.Children, iter)
226		p.nextToken()
227	
228		if p.curToken.Type != ast.TokenIn {
229			return nil, fmt.Errorf("expected 'in' after iterator")
230		}
231	
232		p.nextToken()
233	
234		rng, err := p.parseExpression(0)
235		if err != nil {
236			return nil, err
237		}
238		forNode.Children = append(forNode.Children, rng)
239	
240		if p.curToken.Type != ast.TokenLBrace {
241			return nil, fmt.Errorf("expected '{' for loop body")
242		}
243	
244		body, err := p.parseBlockStmt()
245		if err != nil {
246			return nil, err
247		}
248		forNode.Children = append(forNode.Children, body)
249	
250		return forNode, nil
251	}
252	
253	func (p *Parser) parseReturnStmt() (*ast.Node, error) {
254		retNode := &ast.Node{
255			Kind: ast.NodeReturn,
256			Line: p.curToken.Line,
257			Col:  p.curToken.Col,
258		}
259	
260		p.nextToken() // consume 'return'
261	
262		if p.curToken.Type == ast.TokenSemicolon || p.curToken.Type == ast.TokenRBrace {
263			return retNode, nil
264		}
265	
266		expr, err := p.parseExpression(0)
267		if err != nil {
268			return nil, err
269		}
270		retNode.Children = append(retNode.Children, expr)
271	
272		return retNode, nil
273	}
274	
275	func (p *Parser) parseBlockStmt() (*ast.Node, error) {
276		block := &ast.Node{
277			Kind: ast.NodeBlockStmt,
278			Line: p.curToken.Line,
279			Col:  p.curToken.Col,
280		}
281	
282		p.nextToken() // consume '{'
283	
284		for p.curToken.Type != ast.TokenRBrace && p.curToken.Type != ast.TokenEOF {
285			stmt, err := p.parseStatement()
286			if err != nil {
287				return nil, err
288			}
289			if stmt != nil {
290				block.Children = append(block.Children, stmt)
291			}
292			p.skipSemicolons()
293		}
294	
295		if p.curToken.Type != ast.TokenRBrace {
296			return nil, fmt.Errorf("expected '}'")
297		}
298	
299		p.nextToken() // consume '}'
300	
301		return block, nil
302	}
303	
304	func (p *Parser) parseExpression(prec int) (*ast.Node, error) {
305		left, err := p.parsePrimary()
306		if err != nil {
307			return nil, err
308		}
309	
310		for prec < p.peekPrecedence() {
311			p.nextToken()
312			left, err = p.parseInfix(left)
313			if err != nil {
314				return nil, err
315			}
316		}
317	
318		return left, nil
319	}
320	
321	func (p *Parser) parsePrimary() (*ast.Node, error) {
322		switch p.curToken.Type {
323		case ast.TokenInt:
324			node := &ast.Node{
325				Kind:  ast.NodeIntLit,
326				Value: p.curToken.Value,
327				Line:  p.curToken.Line,
328				Col:   p.curToken.Col,
329			}
330			return node, nil
331	
332		case ast.TokenIdent:
333			node := &ast.Node{
334				Kind:  ast.NodeIdent,
335				Value: p.curToken.Value,
336				Line:  p.curToken.Line,
337				Col:   p.curToken.Col,
338			}
339			return node, nil
340	
341		case ast.TokenLParen:
342			p.nextToken()
343			expr, err := p.parseExpression(0)
344			if err != nil {
345				return nil, err
346			}
347			if p.curToken.Type != ast.TokenRParen {
348				return nil, fmt.Errorf("expected ')'")
349			}
350			return expr, nil
351	
352		default:
353			return nil, fmt.Errorf("unexpected token: %v", p.curToken.Type)
354		}
355	}
356	
357	func (p *Parser) parseInfix(left *ast.Node) (*ast.Node, error) {
358		// Handle field access: obj.field
359		if p.curToken.Type == ast.TokenDot {
360			p.nextToken() // consume '.'
361			if p.curToken.Type != ast.TokenIdent {
362				return nil, fmt.Errorf("expected field name after '.'")
363			}
364			return &ast.Node{
365				Kind:     ast.NodeFieldAccess,
366				Value:    p.curToken.Value,
367				Line:     p.curToken.Line,
368				Col:      p.curToken.Col,
369				Children: []*ast.Node{left},
370			}, nil
371		}
372	
373		node := &ast.Node{
374			Kind:     ast.NodeBinaryExpr,
375			Line:     p.curToken.Line,
376			Col:      p.curToken.Col,
377			Value:    p.curToken.Value,
378			Children: []*ast.Node{left},
379		}
380	
381		prec := p.curPrecedence()
382		p.nextToken()
383	
384		right, err := p.parseExpression(prec)
385		if err != nil {
386			return nil, err
387		}
388		node.Children = append(node.Children, right)
389	
390		// Handle function calls
391		if left.Kind == ast.NodeIdent && p.curToken.Type == ast.TokenLParen {
392			call := &ast.Node{
393				Kind:  ast.NodeCallExpr,
394				Value: left.Value,
395			}
396			p.nextToken() // consume '('
397			for p.curToken.Type != ast.TokenRParen {
398				arg, err := p.parseExpression(0)
399				if err != nil {
400					return nil, err
401				}
402				call.Children = append(call.Children, arg)
403				if p.curToken.Type == ast.TokenComma {
404					p.nextToken()
405				}
406			}
407			p.nextToken() // consume ')'
408			return call, nil
409		}
410	
411		return node, nil
412	}
413	
414	func (p *Parser) peekPrecedence() int {
415		return precedence(p.peekToken.Type)
416	}
417	
418	func (p *Parser) curPrecedence() int {
419		return precedence(p.curToken.Type)
420	}
421	
422	func precedence(tok ast.TokenType) int {
423		switch tok {
424		case ast.TokenEq, ast.TokenNe, ast.TokenLt, ast.TokenGt, ast.TokenLe, ast.TokenGe:
425			return 1
426		case ast.TokenPlus, ast.TokenMinus:
427			return 2
428		case ast.TokenStar, ast.TokenSlash:
429			return 3
430		case ast.TokenDotDot:
431			return 4
432		case ast.TokenDot:
433			return 5
434		default:
435			return 0
436		}
437	}
438	
439	func (p *Parser) skipSemicolons() {
440		for p.curToken.Type == ast.TokenSemicolon {
441			p.nextToken()
442		}
443	}
444	
445	func (p *Parser) parseStructDecl() (*ast.Node, error) {
446		structNode := &ast.Node{
447			Kind: ast.NodeStructDecl,
448			Line: p.curToken.Line,
449			Col:  p.curToken.Col,
450		}
451	
452		p.nextToken() // consume 'struct'
453	
454		if p.curToken.Type != ast.TokenIdent {
455			return nil, fmt.Errorf("expected struct name")
456		}
457	
458		structNode.Value = p.curToken.Value
459		p.nextToken()
460	
461		if p.curToken.Type != ast.TokenLBrace {
462			return nil, fmt.Errorf("expected '{' after struct name")
463		}
464	
465		p.nextToken() // consume '{'
466	
467		// Parse fields
468		for p.curToken.Type != ast.TokenRBrace {
469			field, err := p.parseFieldDecl()
470			if err != nil {
471				return nil, err
472			}
473			structNode.Children = append(structNode.Children, field)
474	
475			if p.curToken.Type == ast.TokenSemicolon {
476				p.nextToken()
477			}
478		}
479	
480		p.nextToken() // consume '}'
481	
482		return structNode, nil
483	}
484	
485	func (p *Parser) parseFieldDecl() (*ast.Node, error) {
486		if p.curToken.Type != ast.TokenIdent {
487			return nil, fmt.Errorf("expected field name")
488		}
489	
490		fieldNode := &ast.Node{
491			Kind:  ast.NodeFieldDecl,
492			Value: p.curToken.Value,
493			Line:  p.curToken.Line,
494			Col:   p.curToken.Col,
495		}
496	
497		p.nextToken() // consume field name
498	
499		if p.curToken.Type != ast.TokenColon {
500			return nil, fmt.Errorf("expected ':' after field name")
501		}
502	
503		p.nextToken() // consume ':'
504	
505		if p.curToken.Type != ast.TokenIdent {
506			return nil, fmt.Errorf("expected field type")
507		}
508	
509		typeNode := &ast.Node{
510			Kind:  ast.NodeIdent,
511			Value: p.curToken.Value,
512			Line:  p.curToken.Line,
513			Col:   p.curToken.Col,
514		}
515		fieldNode.Children = append(fieldNode.Children, typeNode)
516	
517		p.nextToken() // consume type
518	
519		return fieldNode, nil
520	}
