11	// TestConstantFolding validates constant expression optimization
12	func TestConstantFolding(t *testing.T) {
13		// Create AST for "10 + 5"
14		node := &ast.Node{
15			Kind:  ast.NodeBinaryExpr,
16			Value: "+",
17			Children: []*ast.Node{
18				{Kind: ast.NodeIntLit, Value: "10"},
19				{Kind: ast.NodeIntLit, Value: "5"},
20			},
21		}
22	
23		result := ConstantFoldingRule.Apply(node)
24		if result == nil {
25			t.Errorf("expected optimized result, got nil")
26		}
27		if result.Kind != ast.NodeIntLit {
28			t.Errorf("expected IntLit after folding, got %d", result.Kind)
29		}
30		if result.Value != "15" {
31			t.Errorf("expected value 15, got %s", result.Value)
32		}
33	}
