86	// TestConstantFoldingNested validates nested constant expressions
87	func TestConstantFoldingNested(t *testing.T) {
88		// (10 + 5) * 2
89		node := &ast.Node{
90			Kind:  ast.NodeBinaryExpr,
91			Value: "*",
92			Children: []*ast.Node{
93				{
94					Kind:  ast.NodeBinaryExpr,
95					Value: "+",
96					Children: []*ast.Node{
97						{Kind: ast.NodeIntLit, Value: "10"},
98						{Kind: ast.NodeIntLit, Value: "5"},
99					},
100				},
101				{Kind: ast.NodeIntLit, Value: "2"},
102			},
103		}
