105		result := ConstantFoldingRule.Apply(node)
106		// Inner expression should be folded first
107		if result.Kind == ast.NodeBinaryExpr {
108			// Check if left child was folded
109			if result.Children[0].Kind == ast.NodeIntLit {
110				t.Logf("Inner expression folded to %s", result.Children[0].Value)
111			}
112		}
