126	// TestAdaptiveOptimizerPriorities validates priority adjustment
127	func TestAdaptiveOptimizerPriorities(t *testing.T) {
128		db := &profiler.Database{
129			Patterns: []profiler.PatternEntry{
130				{
131					Kind:      "ConstantExpr",
132					Signature: "expr1",
133					Count:     100,
134				},
135				{
136					Kind:      "DeadAssign",
137					Signature: "var1",
138					Count:     50,
139				},
140			},
141		}
142	
143		opt := NewAdaptiveOptimizer()
144		opt.UpdatePriorities(db)
145	
146		priorities := opt.GetRulePriorities()
147		if len(priorities) == 0 {
148			t.Errorf("expected priorities, got none")
149		}
150	
151		// ConstantFolding should have higher priority than DeadCodeElimination
152		cfPriority := priorities["ConstantFolding"]
153		dcePriority := priorities["DeadCodeElimination"]
154	
155		if cfPriority <= dcePriority {
156			t.Errorf("ConstantFolding should have higher priority than DeadCodeElimination, got %d vs %d",
157				cfPriority, dcePriority)
158		}
159	}
