203	// TestParsePatternKind validates kind conversion
204	func TestParsePatternKind(t *testing.T) {
205		tests := []struct {
206			input    string
207			expected profiler.PatternKind
208		}{
209			{"ConstantExpr", profiler.PatternConstantExpr},
210			{"DeadAssign", profiler.PatternDeadAssign},
211			{"InlinableCall", profiler.PatternInlinableCall},
