9	// OptimizationRule defines a transformation rule
10	type OptimizationRule struct {
11		Name            string
12		TargetPattern   profiler.PatternKind
13		Priority        int
14		Description     string
15		Apply           func(*ast.Node) *ast.Node
16	}
17	
18	// ConstantFoldingRule evaluates constant expressions at compile time
19	var ConstantFoldingRule OptimizationRule
20	
21	func initConstantFoldingRule() {
22		ConstantFoldingRule = OptimizationRule{
23			Name:          "ConstantFolding",
24			TargetPattern: profiler.PatternConstantExpr,
25			Priority:      100,
26			Description:   "Evaluate constant expressions at compile time",
27			Apply: func(node *ast.Node) *ast.Node {
28				if node == nil {
29					return node
30				}
31	
32				// If it's a binary expression with two integer literals
33				if node.Kind == ast.NodeBinaryExpr && len(node.Children) == 2 {
34					left, right := node.Children[0], node.Children[1]
35	
36					if left.Kind == ast.NodeIntLit && right.Kind == ast.NodeIntLit {
37						result := evaluateConstExpr(node)
38						if result != nil {
39							return result
40						}
41					}
42				}
43	
44				// Recursively apply to children
45				for i, child := range node.Children {
46					node.Children[i] = ConstantFoldingRule.Apply(child)
47				}
48	
49				return node
50			},
51		}
52	}
53	
