129			{"a * b", []ast.TokenType{ast.TokenStar}},
130			{"x > 5", []ast.TokenType{ast.TokenGt}},
131			{"a == b", []ast.TokenType{ast.TokenEq}},
132		}
133	
134		for _, tt := range tests {
135			p := New(tt.input)
