1	// Package profiler implements pattern detection and frequency tracking
2	package profiler
3	
4	import (
5		"fmt"
6		"hash/fnv"
7	
8		"github.com/user/freelang-evolving-compiler/internal/ast"
9	)
10	
11	// PatternKind identifies the type of pattern
12	type PatternKind int
13	
14	const (
15		PatternConstantExpr PatternKind = iota
16		PatternDeadAssign
17		PatternInlinableCall
18		PatternLoopInvariant
19		PatternRepeatedSubExpr
20	)
21	
22	func (pk PatternKind) String() string {
23		switch pk {
24		case PatternConstantExpr:
25			return "ConstantExpr"
26		case PatternDeadAssign:
27			return "DeadAssign"
28		case PatternInlinableCall:
29			return "InlinableCall"
30		case PatternLoopInvariant:
31			return "LoopInvariant"
32		case PatternRepeatedSubExpr:
33			return "RepeatedSubExpr"
34		default:
35			return "Unknown"
36		}
37	}
38	
39	// Pattern represents a detected pattern with frequency and optimization benefit
40	type Pattern struct {
41		Kind      PatternKind `json:"kind"`
42		Signature string      `json:"signature"`
43		Count     int64       `json:"count"`
44		SavedNs   int64       `json:"saved_ns"`
45	}
46	
47	// PatternSignature generates a unique identifier for an AST node
48	func PatternSignature(node *ast.Node) string {
49		if node == nil {
50			return "nil"
51		}
52	
53		h := fnv.New64a()
54		h.Write([]byte(nodeKindStr(node.Kind)))
55	
56		if node.Value != "" {
57			h.Write([]byte("|"))
58			h.Write([]byte(node.Value))
59		}
60	
61		for _, child := range node.Children {
62			h.Write([]byte("|"))
63			h.Write([]byte(PatternSignature(child)))
64		}
65	
66		return fmt.Sprintf("%x", h.Sum64())
67	}
68	
69	// PatternType determines what kind of pattern this node represents
70	func PatternType(node *ast.Node, context *PatternContext) PatternKind {
71		if node == nil {
72			return 0
73		}
74	
75		// Constant expression: both operands are literals
76		if node.Kind == ast.NodeBinaryExpr && len(node.Children) == 2 {
77			left, right := node.Children[0], node.Children[1]
78			if isLiteral(left) && isLiteral(right) {
79				return PatternConstantExpr
80			}
81		}
82	
83		// Inlinable call: function body is simple (single expression)
84		if node.Kind == ast.NodeCallExpr {
85			if fnName, ok := findFunctionDef(node.Value, context.Program); ok {
86				if fnName.Kind == ast.NodeFnDecl && len(fnName.Children) > 0 {
87					body := fnName.Children[len(fnName.Children)-1]
88					if body.Kind == ast.NodeBlockStmt && len(body.Children) <= 1 {
89						return PatternInlinableCall
90					}
91				}
92			}
93		}
94	
95		return 0
96	}
97	
98	// isLiteral checks if node is a literal (int, bool, string)
99	func isLiteral(node *ast.Node) bool {
100		if node == nil {
101			return false
102		}
103		return node.Kind == ast.NodeIntLit
104	}
105	
106	// PatternContext holds information for pattern analysis
107	type PatternContext struct {
108		Program           *ast.Node
109		VariableUsage     map[string]int    // usage count per variable
110		InLoop            bool              // whether we're inside a loop
111		LoopInvariants    map[string]bool   // expressions that don't depend on loop var
112		RepeatedExprs     map[string]int    // frequency of sub-expressions
113		FunctionCalls     map[string]int    // frequency of function calls
114		AssignedVars      map[string]bool   // variables that are assigned
115		ReadVars          map[string]bool   // variables that are read
116	}
117	
118	// NewPatternContext creates a new pattern analysis context
119	func NewPatternContext(program *ast.Node) *PatternContext {
120		return &PatternContext{
121			Program:        program,
122			VariableUsage:  make(map[string]int),
123			LoopInvariants: make(map[string]bool),
124			RepeatedExprs:  make(map[string]int),
125			FunctionCalls:  make(map[string]int),
126			AssignedVars:   make(map[string]bool),
127			ReadVars:       make(map[string]bool),
128		}
129	}
130	
131	// AnalyzeNode recursively analyzes a node for patterns
132	func (pc *PatternContext) AnalyzeNode(node *ast.Node) {
133		if node == nil {
134			return
135		}
136	
137		switch node.Kind {
138		case ast.NodeLetDecl:
139			if len(node.Children) > 0 {
140				varName := node.Children[0].Value
141				pc.AssignedVars[varName] = true
142			}
143			for _, child := range node.Children {
144				pc.AnalyzeNode(child)
145			}
146	
147		case ast.NodeIdent:
148			pc.VariableUsage[node.Value]++
149			pc.ReadVars[node.Value] = true
150	
151		case ast.NodeBinaryExpr:
152			sig := PatternSignature(node)
153			pc.RepeatedExprs[sig]++
154			for _, child := range node.Children {
155				pc.AnalyzeNode(child)
156			}
157	
158		case ast.NodeCallExpr:
159			pc.FunctionCalls[node.Value]++
160			for _, child := range node.Children {
161				pc.AnalyzeNode(child)
162			}
163	
164		case ast.NodeForStmt:
165			oldInLoop := pc.InLoop
166			pc.InLoop = true
167			for _, child := range node.Children {
168				pc.AnalyzeNode(child)
169			}
170			pc.InLoop = oldInLoop
171	
172		default:
173			for _, child := range node.Children {
174				pc.AnalyzeNode(child)
175			}
176		}
177	}
178	
179	// DetectDeadAssigns finds variables assigned but never read
180	func (pc *PatternContext) DetectDeadAssigns() []string {
181		var deadAssigns []string
182		for varName := range pc.AssignedVars {
183			if !pc.ReadVars[varName] {
184				deadAssigns = append(deadAssigns, varName)
185			}
186		}
187		return deadAssigns
188	}
