233	// SignaturePattern is a pattern with its count per build
234	type SignaturePattern struct {
235		Signature string
236		Kind      PatternKind
237		Count     int64
238		SavedNs   int64
239	}
240	
241	// TopPatterns returns the top N most frequent patterns
242	func (pc *PatternContext) TopPatterns(n int) []SignaturePattern {
243		patterns := make([]SignaturePattern, 0)
244	
245		// Collect repeated expressions
246		for sig, count := range pc.RepeatedExprs {
247			if count > 1 {
248				patterns = append(patterns, SignaturePattern{
249					Signature: sig,
250					Kind:      PatternRepeatedSubExpr,
251					Count:     int64(count),
252					SavedNs:   0,
253				})
254			}
255		}
256	
257		// Collect function calls
258		for fnName, count := range pc.FunctionCalls {
259			patterns = append(patterns, SignaturePattern{
260				Signature: "CallExpr:" + fnName,
261				Kind:      PatternInlinableCall,
262				Count:     int64(count),
263				SavedNs:   0,
264			})
265		}
266	
267		// Sort by count (simple bubble sort for small N)
268		for i := 0; i < len(patterns)-1; i++ {
269			for j := i + 1; j < len(patterns); j++ {
270				if patterns[j].Count > patterns[i].Count {
271					patterns[i], patterns[j] = patterns[j], patterns[i]
272				}
273			}
274		}
275	
276		// Return top N
277		if n > len(patterns) {
278			n = len(patterns)
279		}
280		return patterns[:n]
281	}
